data.code-hoàn-chỉnh#Code hoàn chỉnh:
import asyncio from typing import TypedDict, Annotated from langgraph.graph import StateGraph, START, END from langgraph.graph.message import add_messages from langchain_openai import ChatOpenAI from langchain_core.messages import HumanMessage, SystemMessage, BaseMessage from langchain_core.tools import tool # ==================== STATE ==================== class ResearchState(TypedDict, total=False): """State cho Planning Agent.""" messages: Annotated[list[BaseMessage], add_messages] query: str # Câu hỏi gốc query_type: str # Loại câu hỏi (factual, analytical, creative) research_plan: list[str] # Kế hoạch nghiên cứu search_results: list[str] # Kết quả tìm kiếm draft: str # Bản nháp câu trả lời quality_score: float # Điểm chất lượng (0-1) iteration: int # Số lần lặp error: str # Thông báo lỗi (nếu có) # ==================== TOOLS ==================== @tool def web_search(query: str) -> str: """Tìm kiếm thông tin trên web. Args: query: Từ khóa tìm kiếm cụ thể """ # Placeholder — thay bằng API thực tế (Tavily, SerpAPI, v.v.) return f"[Kết quả tìm kiếm cho '{query}']: Thông tin mẫu..." # ==================== NODES ==================== async def analyze_node(state: ResearchState) -> dict: """Phân tích câu hỏi của người dùng.""" llm = ChatOpenAI(model="gpt-4o-mini", temperature=0) query = state.get("query", "") if not query and state.get("messages"): last_msg = state["messages"][-1] query = last_msg.content if hasattr(last_msg, "content") else str(last_msg) prompt = f"""Phân tích câu hỏi sau và xác định loại. Câu hỏi: {query} Trả về JSON: {{ "query_type": "factual|analytical|creative", "needs_research": true/false }} Chỉ trả về JSON, không thêm gì khác.""" response = await llm.ainvoke([HumanMessage(content=prompt)]) import json try: analysis = json.loads(response.content) except json.JSONDecodeError: analysis = {"query_type": "factual", "needs_research": True} return { "query": query, "query_type": analysis.get("query_type", "factual"), "iteration": 0, } async def plan_node(state: ResearchState) -> dict: """Lập kế hoạch nghiên cứu.""" llm = ChatOpenAI(model="gpt-4o-mini", temperature=0) query = state.get("query", "") query_type = state.get("query_type", "factual") prompt = f"""Lập kế hoạch nghiên cứu cho câu hỏi sau. Câu hỏi: {query} Loại: {query_type} Liệt kê 3-5 bước tìm kiếm cần thực hiện, mỗi bước là một câu truy vấn tìm kiếm. Trả về danh sách JSON array các string. Chỉ trả về JSON array.""" response = await llm.ainvoke([HumanMessage(content=prompt)]) import json try: plan = json.loads(response.content) if not isinstance(plan, list): plan = [query] except json.JSONDecodeError: plan = [query] return {"research_plan": plan} async def research_node(state: ResearchState) -> dict: """Thực hiện tìm kiếm theo kế hoạch.""" plan = state.get("research_plan", []) results = [] for search_query in plan: try: result = web_search.invoke({"query": search_query}) results.append(f"Query: {search_query}
Result: {result}") except Exception as e: results.append(f"Query: {search_query}
Error: {str(e)}") iteration = state.get("iteration", 0) + 1 return { "search_results": results, "iteration": iteration, } async def synthesize_node(state: ResearchState) -> dict: """Tổng hợp kết quả thành câu trả lời.""" llm = ChatOpenAI(model="gpt-4o-mini") query = state.get("query", "") search_results = state.get("search_results", []) prompt = f"""Dựa trên kết quả nghiên cứu, viết câu trả lời chi tiết cho câu hỏi. Câu hỏi: {query} Kết quả nghiên cứu: {chr(10).join(search_results)} Yêu cầu: - Trả lời đầy đủ, có cấu trúc rõ ràng - Trích dẫn nguồn khi có thể - Nếu thông tin không đủ, ghi chú điều cần bổ sung - Viết bằng tiếng Việt""" response = await llm.ainvoke([HumanMessage(content=prompt)]) return {"draft": response.content} async def review_node(state: ResearchState) -> dict: """Đánh giá chất lượng câu trả lời.""" llm = ChatOpenAI(model="gpt-4o-mini", temperature=0) query = state.get("query", "") draft = state.get("draft", "") prompt = f"""Đánh giá chất lượng câu trả lời sau trên thang 0-1. Câu hỏi: {query} Câu trả lời: {draft} Tiêu chí: - Độ đầy đủ: Có trả lời đủ câu hỏi không? - Độ chính xác: Thông tin có đáng tin không? - Độ rõ ràng: Có dễ hiểu không? Trả về JSON: {{"score": 0.0-1.0, "needs_more": true/false, "feedback": "..."}} Chỉ trả về JSON.""" response = await llm.ainvoke([HumanMessage(content=prompt)]) import json try: review = json.loads(response.content) score = float(review.get("score", 0.5)) except (json.JSONDecodeError, ValueError): score = 0.5 review = {"needs_more": True, "feedback": "Không thể parse review"} return {"quality_score": score} # ==================== ROUTING ==================== def should_continue_research(state: ResearchState) -> str: """Quyết định có cần nghiên cứu thêm không.""" score = state.get("quality_score", 0.0) iteration = state.get("iteration", 0) # Nếu chất lượng đủ tốt hoặc đã lặp quá nhiều lần → kết thúc if score >= 0.7 or iteration >= 3: return "finalize" # Ngược lại → nghiên cứu thêm return "research" # ==================== BUILD GRAPH ==================== async def finalize_node(state: ResearchState) -> dict: """Chuẩn bị câu trả lời cuối cùng.""" from langchain_core.messages import AIMessage draft = state.get("draft", "Không thể tạo câu trả lời.") return {"messages": [AIMessage(content=draft)]} graph = StateGraph(ResearchState) # Thêm nodes graph.add_node("analyze", analyze_node) graph.add_node("plan", plan_node) graph.add_node("research", research_node) graph.add_node("synthesize", synthesize_node) graph.add_node("review", review_node) graph.add_node("finalize", finalize_node) # Thêm edges graph.add_edge(START, "analyze") graph.add_edge("analyze", "plan") graph.add_edge("plan", "research") graph.add_edge("research", "synthesize") graph.add_edge("synthesize", "review") # Conditional edge từ review graph.add_conditional_edges( "review", should_continue_research, { "research": "research", # Lặp lại nghiên cứu "finalize": "finalize", # Hoàn thành } ) graph.add_edge("finalize", END) # Compile app = graph.compile() # ==================== CHẠY ==================== async def main(): result = await app.ainvoke({ "messages": [HumanMessage(content="AI agents đang thay đổi ngành phần mềm như thế nào?")], "query": "AI agents đang thay đổi ngành phần mềm như thế nào?" }) print("=" * 60) print("CÂU TRẢ LỜI:") print("=" * 60) print(result.get("draft", "Không có kết quả")) print(f"
Số lần lặp: {result.get('iteration', 0)}") print(f"Điểm chất lượng: {result.get('quality_score', 0):.2f}") if __name__ == "__main__": asyncio.run(main()) 💡 MẸO: Khi xây dựng graph phức tạp, hãy bắt đầu với version đơn giản nhất (linear flow), sau đó thêm conditional edges và loops dần. Đừng cố xây dựng graph hoàn hảo ngay từ đầu — iterate như cách bạn iterate code.

data.async-generators-với-langgraph#Async Gen:
LangGraph hỗ trợ streaming qua astream và astream_events:
from langchain_core.messages import HumanMessage @app.post("/api/v1/agent/stream") async def agent_stream(request: ChatRequest): """Stream response từ LangGraph agent.""" async def stream_generator(): """Stream tokens từ LangGraph agent.""" config = { "configurable": { "thread_id": request.conversation_id or "default", } } inputs = { "messages": [HumanMessage(content=request.message)] } async for event in agent.astream_events(inputs, config, version="v2"): kind = event.get("event") if kind == "on_chat_model_stream": # Token mới từ LLM token = event["data"]["chunk"].content if token: yield f"data: {json.dumps({'type': 'token', 'content': token})}

" elif kind == "on_tool_start": # Agent bắt đầu gọi tool tool_name = event.get("name", "unknown") yield f"data: {json.dumps({'type': 'tool_start', 'tool': tool_name})}

" elif kind == "on_tool_end": # Tool hoàn thành tool_name = event.get("name", "unknown") output = str(event["data"].get("output", ""))[:200] yield f"data: {json.dumps({'type': 'tool_end', 'tool': tool_name, 'preview': output})}

" yield f"data: {json.dumps({'type': 'done'})}

" return StreamingResponse( stream_generator(), media_type="text/event-stream", ) 🔑 ĐIỂM CHÍNH: Streaming là “must-have” cho AI chat applications. Người dùng không muốn nhìn vào màn hình trống trong 10-30 giây. SSE là chuẩn đơn giản nhất — client chỉ cần EventSource hoặc fetch với ReadableStream.

