data.ví-dụ-hoàn-chỉnh#Ví dụ hoàn chỉnh:
# main.py — File chính chạy API import os import logging from contextlib import asynccontextmanager from fastapi import FastAPI, HTTPException from fastapi.middleware.cors import CORSMiddleware from fastapi.responses import StreamingResponse from pydantic import BaseModel, Field from typing import Optional from datetime import datetime # Cấu hình logging logging.basicConfig(level=logging.INFO) logger = logging.getLogger("ai20k_api") # ==================== SCHEMAS ==================== class ChatRequest(BaseModel): message: str = Field(..., min_length=1, max_length=5000) conversation_id: Optional[str] = None stream: bool = False class ChatResponse(BaseModel): response: str conversation_id: str sources: list[str] = [] timestamp: datetime = Field(default_factory=datetime.now) class HealthResponse(BaseModel): status: str version: str agent_ready: bool # ==================== LIFESPAN ==================== @asynccontextmanager async def lifespan(app: FastAPI): # Startup logger.info("Khởi tạo AI20K Agent API...") from agent import build_graph app.state.agent = build_graph() logger.info("Agent đã sẵn sàng!") yield # Shutdown logger.info("Đóng API...") # ==================== APP ==================== app = FastAPI( title="AI20K Agent API", version="1.0.0", lifespan=lifespan, ) # CORS app.add_middleware( CORSMiddleware, allow_origins=os.getenv("ALLOWED_ORIGINS", "http://localhost:3000").split(","), allow_credentials=True, allow_methods=["*"], allow_headers=["*"], ) # ==================== ROUTES ==================== @app.get("/health", response_model=HealthResponse) async def health(): return HealthResponse( status="healthy", version="1.0.0", agent_ready=hasattr(app.state, "agent"), ) @app.post("/api/v1/chat", response_model=ChatResponse) async def chat(request: ChatRequest): """Chat với agent — trả về response hoàn chỉnh.""" from langchain_core.messages import HumanMessage agent = app.state.agent try: result = await agent.ainvoke({ "messages": [HumanMessage(content=request.message)], "query": request.message, }) except TimeoutError: raise HTTPException(status_code=504, detail="Agent timeout") except Exception as e: logger.error(f"Agent error: {e}", exc_info=True) raise HTTPException(status_code=503, detail="Agent không khả dụng") return ChatResponse( response=result.get("draft", "Không thể tạo câu trả lời"), conversation_id=request.conversation_id or "conv-001", sources=result.get("search_results", []), ) @app.post("/api/v1/chat/stream") async def chat_stream(request: ChatRequest): """Chat với agent — stream response.""" import json from langchain_core.messages import HumanMessage agent = app.state.agent async def generate(): try: async for event in agent.astream_events( {"messages": [HumanMessage(content=request.message)]}, config={"configurable": {"thread_id": request.conversation_id or "default"}}, version="v2", ): if event["event"] == "on_chat_model_stream": token = event["data"]["chunk"].content if token: yield f"data: {json.dumps({'type': 'token', 'content': token})}

" yield f"data: {json.dumps({'type': 'done'})}

" except Exception as e: yield f"data: {json.dumps({'type': 'error', 'message': str(e)})}

" return StreamingResponse(generate(), media_type="text/event-stream") # ==================== RUN ==================== if __name__ == "__main__": import uvicorn uvicorn.run( "main:app", host="0.0.0.0", port=8000, reload=True, # Auto-reload khi code thay đổi (development only) ) 🔑 ĐIỂM CHÍNH: Lifespan pattern là cách đúng để khởi tạo LangGraph agent trong FastAPI. Agent được tạo một lần khi app start và được tái sử dụng cho mọi request. Điều này tránh overhead tạo graph mỗi request và cho phép agent duy trì state (nếu dùng checkpointer).

data.markdown-rendering#Markdown Rendering:
AI agent thường trả về markdown (headers, lists, code blocks). Hiển thị markdown trong React:
npm install react-markdown remark-gfm rehype-highlight // src/components/MarkdownRenderer.tsx "use client"; import ReactMarkdown from "react-markdown"; import remarkGfm from "remark-gfm"; import rehypeHighlight from "rehype-highlight"; interface MarkdownRendererProps { content: string; } export default function MarkdownRenderer({ content }: MarkdownRendererProps) { return ( <ReactMarkdown remarkPlugins={[remarkGfm]} rehypePlugins={[rehypeHighlight]} components={{ // Custom rendering cho code blocks code({ inline, className, children, ...props }) { if (inline) { return ( <code className="bg-gray-100 dark:bg-gray-800 px-1.5 py-0.5 rounded text-sm" {...props} > {children} </code> ); } return ( <div className="relative my-3"> <pre className="bg-gray-900 text-gray-100 rounded-lg p-4 overflow-x-auto"> <code className={className} {...props}> {children} </code> </pre> </div> ); }, // Custom rendering cho links a({ href, children }) { return ( <a href={href} target="_blank" rel="noopener noreferrer" className="text-blue-500 hover:underline" > {children} </a> ); }, // Custom rendering cho tables table({ children }) { return ( <div className="overflow-x-auto my-3"> <table className="min-w-full border-collapse border border-gray-300 dark:border-gray-700"> {children} </table> </div> ); }, }} > {content} </ReactMarkdown> ); } Cập nhật ChatMessage để dùng MarkdownRenderer:
// Cập nhật ChatMessage component import MarkdownRenderer from "./MarkdownRenderer"; // Trong ChatMessage, thay thế: // {message.content} // bằng: <MarkdownRenderer content={message.content} /> 🔑 ĐIỂM CHÍNH: Streaming display là yếu tố then chốt cho UX của AI chat. Người dùng thấy câu trả lời xuất hiện từng phần, tạo cảm giác “AI đang suy nghĩ và trả lời”. Kết hợp với markdown rendering, bạn có giao diện chat chuyên nghiệp, tương tự ChatGPT.
💡 MẸO: Thêm cursor blinking animation khi đang stream để người dùng biết AI vẫn đang sinh nội dung:
/* Thêm vào globals.css */ .typing-cursor::after { content: "▋"; animation: blink 1s infinite; } @keyframes blink { 0%, 50% { opacity: 1; } 51%, 100% { opacity: 0; } }

data.pages-và-layouts#Pages và Layouts:
Root Layout (src/app/layout.tsx) là bao bọc cho toàn bộ ứng dụng:
// src/app/layout.tsx import type { Metadata } from "next"; import { Inter } from "next/font/google"; import "./globals.css"; import { ThemeProvider } from "@/components/ThemeProvider"; const inter = Inter({ subsets: ["latin"] }); export const metadata: Metadata = { title: "AI20K Chat", description: "AI Agent Chat Application", }; export default function RootLayout({ children, }: { children: React.ReactNode; }) { return ( <html lang="vi" suppressHydrationWarning> <body className={inter.className}> <ThemeProvider> {children} </ThemeProvider> </body> </html> ); } Home Page (src/app/page.tsx):
// src/app/page.tsx import Link from "next/link"; export default function Home() { return ( <main className="flex min-h-screen flex-col items-center justify-center p-8"> <div className="max-w-2xl text-center"> <h1 className="text-4xl font-bold mb-4"> AI20K Agent </h1> <p className="text-lg text-gray-600 dark:text-gray-400 mb-8"> Trợ lý AI thông minh sẵn sàng giúp bạn nghiên cứu, phân tích và trả lời câu hỏi. </p> <Link href="/chat" className="inline-block bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 transition-colors font-medium" > Bắt đầu trò chuyện </Link> </div> </main> ); } Chat Page (src/app/chat/page.tsx):
// src/app/chat/page.tsx "use client"; import { useState } from "react"; import ChatMessage from "@/components/ChatMessage"; import ChatInput from "@/components/ChatInput"; import { Message } from "@/types/chat"; export default function ChatPage() { const [messages, setMessages] = useState<Message[]>([]); const [isLoading, setIsLoading] = useState(false); const handleSend = async (content: string) => { // Thêm user message const userMessage: Message = { id: Date.now().toString(), role: "user", content, timestamp: new Date(), }; setMessages((prev) => [...prev, userMessage]); setIsLoading(true); try { // Gọi API const response = await fetch("http://localhost:8000/api/v1/chat", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ message: content }), }); const data = await response.json(); const assistantMessage: Message = { id: (Date.now() + 1).toString(), role: "assistant", content: data.response, sources: data.sources, timestamp: new Date(), }; setMessages((prev) => [...prev, assistantMessage]); } catch (error) { console.error("Chat error:", error); } finally { setIsLoading(false); } }; return ( <div className="flex flex-col h-screen max-w-4xl mx-auto"> {/* Header */} <header className="border-b p-4"> <h1 className="text-xl font-semibold">AI20K Agent</h1> </header> {/* Messages */} <div className="flex-1 overflow-y-auto p-4 space-y-4"> {messages.length === 0 ? ( <div className="text-center text-gray-500 mt-20"> Gửi tin nhắn để bắt đầu trò chuyện </div> ) : ( messages.map((msg) => ( <ChatMessage key={msg.id} message={msg} /> )) )} {isLoading && ( <div className="text-gray-500 animate-pulse"> Đang suy nghĩ... </div> )} </div> {/* Input */} <ChatInput onSend={handleSend} disabled={isLoading} /> </div> ); } 💡 MẸO: "use client" directive ở đầu file cho Next.js biết đây là Client Component — component chạy ở browser, có thể dùng useState, useEffect, event handlers. Mặc định tất cả components trong App Router là Server Components (chạy ở server). Dùng "use client" chỉ khi cần interactivity.
